steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      {
        projects(filter: {name: {contains: \"Checkout Redesign\"}}) {
          nodes {
            id
            name
            issues {
              nodes {
                id
                identifier
                title
                priority
                milestone {
                  id
                  name
                  state
                  targetDate
                }
              }
            }
          }
        }
      }
    "
  }'
